const moveKanbanCard = `-- name: MoveKanbanCard :one
UPDATE kanban_cards c SET column_id = $1, position = $2, updated_at = NOW()
FROM kanban_boards b, kanban_columns col
WHERE c.id = $3 AND c.board_id = b.id AND b.owner_id = $4
  AND col.id = $1 AND col.board_id = c.board_id AND c.archived_at IS NULL
  AND (c.column_id = col.id OR col.wip_limit IS NULL OR (SELECT COUNT(*) FROM kanban_cards k WHERE k.column_id = col.id AND k.archived_at IS NULL) < col.wip_limit)
RETURNING c.id, c.board_id, c.column_id, c.source_project_id, c.kind, c.title, c.description, c.priority, c.position, c.due_at, c.external_key, c.custom_fields, c.archived_at, c.created_at, c.updated_at
`

type MoveKanbanCardParams struct {
	ColumnID uuid.UUID `json:"column_id"`
	Position int64     `json:"position"`
	ID       uuid.UUID `json:"id"`
	OwnerID  uuid.UUID `json:"owner_id"`
}

func (q *Queries) MoveKanbanCard(ctx context.Context, arg MoveKanbanCardParams) (KanbanCard, error) {
	row := q.db.QueryRow(ctx, moveKanbanCard,
		arg.ColumnID,
		arg.Position,
		arg.ID,
		arg.OwnerID,
	)
	var i KanbanCard
	err := row.Scan(
		&i.ID,
		&i.BoardID,
		&i.ColumnID,
		&i.SourceProjectID,
		&i.Kind,
		&i.Title,
		&i.Description,
		&i.Priority,
		&i.Position,
		&i.DueAt,
		&i.ExternalKey,
		&i.CustomFields,
		&i.ArchivedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

